"use client"

import * as React from "react"
import { Questionnaire as QuestionnairePrimitive } from "@shadcn/react/questionnaire"
import { cn } from "@/serigraph/lib/utils"
import { Kbd } from "@/serigraph/ui/kbd"

// The answering parts of a questionnaire. A choice is a row with the box radius, just the edge line on whatever is
// beneath, which takes a tint under the pointer; chosen, it takes the highlight inside an ink line, and its box (a
// rounded square for several answers, a circle for one) takes a fine ink tick or a solid ink dot, so colour is never
// the only sign. Shortcut letters sit on keys. An unanswered required choice has a rose second ring, and the error
// reads in ink after a rose dot. A typed answer is a field.
export const TICK = "M2.5 7.4 5.6 10.3 11.5 3.6"

function QuestionnaireChoice({
  children,
  className,
  value,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Choice>) {
  return (
    <QuestionnairePrimitive.Choice
      data-slot="questionnaire-choice"
      value={value}
      className={cn(
        "group/questionnaire-choice relative flex min-h-control cursor-pointer items-start gap-tight rounded-box border-(length:--line) border-(--edge,var(--ink)) px-snug py-[0.6875rem] text-start font-read text-body leading-ui text-(--text,var(--ink)) transition-colors duration-(--duration-control) ease-(--ease) select-none",
        "hover:not-data-disabled:not-data-checked:bg-[color-mix(in_oklab,var(--surface,var(--canvas))_70%,var(--paper))]",
        "data-checked:border-ink data-checked:bg-highlight data-checked:text-ink data-checked:[--surface:var(--highlight)] data-checked:[--text:var(--ink)] data-checked:[--edge:var(--ink)]",
        "data-invalid:outline-(length:--line) data-invalid:outline-offset-3 data-invalid:outline-rose",
        "has-[>input:focus-visible]:outline-(length:--line) has-[>input:focus-visible]:outline-offset-3 has-[>input:focus-visible]:outline-(--ring,var(--edge,var(--ink))) data-invalid:has-[>input:focus-visible]:outline-[calc(var(--line)*2)] data-invalid:has-[>input:focus-visible]:outline-rose",
        "data-disabled:cursor-not-allowed data-disabled:border-(--text-quiet,var(--ink-quiet)) data-disabled:text-(--text-quiet,var(--ink-quiet))",
        "forced-colors:data-checked:border-[calc(var(--line)*2)]",
        className,
      )}
      {...props}
    >
      <QuestionnairePrimitive.ChoiceInput
        data-slot="questionnaire-choice-input"
        className="absolute inset-0 z-10 size-full cursor-pointer appearance-none rounded-[inherit] bg-transparent outline-none disabled:cursor-not-allowed"
      />
      <span
        aria-hidden="true"
        data-slot="questionnaire-choice-indicator"
        className="pointer-events-none relative mt-px grid size-5 shrink-0 place-items-center rounded-[0.375rem] border-(length:--line) border-(--edge,var(--ink)) bg-[color-mix(in_oklab,var(--surface,var(--canvas))_30%,var(--paper))] text-ink group-data-checked/questionnaire-choice:border-ink group-data-checked/questionnaire-choice:bg-highlight group-data-disabled/questionnaire-choice:border-(--text-quiet,var(--ink-quiet)) group-data-[type=radio]/questionnaire-choice:rounded-full"
      >
        <svg
          data-slot="questionnaire-choice-indicator-check"
          viewBox="0 0 14 14"
          className="hidden size-3.5 fill-none stroke-current [stroke-linecap:round] [stroke-linejoin:round] [[data-checked][data-type=checkbox]_&]:block"
        >
          <path d={TICK} strokeWidth={1.6} />
        </svg>
        <svg
          data-slot="questionnaire-choice-indicator-dot"
          viewBox="0 0 8 8"
          className="hidden size-2 fill-current [[data-checked][data-type=radio]_&]:block"
        >
          <circle cx="4" cy="4" r="4" />
        </svg>
      </span>
      <QuestionnairePrimitive.ChoiceLabel
        data-slot="questionnaire-choice-label"
        className="flex min-w-0 flex-1 flex-col gap-0.5 pt-px"
      >
        {children}
      </QuestionnairePrimitive.ChoiceLabel>
      <QuestionnairePrimitive.ChoiceShortcut
        data-slot="questionnaire-choice-shortcut"
        render={<Kbd />}
        className="ms-auto"
      />
    </QuestionnairePrimitive.Choice>
  )
}

function QuestionnaireChoiceDescription({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="questionnaire-choice-description"
      className={cn("text-small leading-small", className)}
      {...props}
    />
  )
}

function QuestionnaireInput({
  className,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Input>) {
  return (
    <div
      data-slot="questionnaire-input-wrapper"
      className="group/questionnaire-input relative w-full min-w-0"
    >
      <QuestionnairePrimitive.Input
        data-slot="questionnaire-input"
        className={cn(
          "control-field h-control w-full min-w-0 px-snug py-0",
          className,
        )}
        {...props}
      />
    </div>
  )
}

function QuestionnaireError({
  className,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Error>) {
  return (
    <QuestionnairePrimitive.Error
      data-slot="questionnaire-error"
      className={cn(
        "m-0 flex items-start gap-hair text-small leading-small text-(--text,var(--ink)) before:mt-[calc((1lh-0.5rem)/2)] before:size-2 before:shrink-0 before:rounded-full before:border-(length:--line) before:border-ink before:bg-rose forced-colors:before:bg-[CanvasText]",
        className,
      )}
      {...props}
    />
  )
}

export {
  QuestionnaireChoice,
  QuestionnaireChoiceDescription,
  QuestionnaireError,
  QuestionnaireInput,
}

"use client"

import * as React from "react"
import { Questionnaire as QuestionnairePrimitive } from "@shadcn/react/questionnaire"
import { cn } from "@/serigraph/lib/utils"
import { buttonVariants, type Button } from "@/serigraph/ui/button"
import {
  QuestionnaireChoice,
  QuestionnaireChoiceDescription,
  QuestionnaireError,
  QuestionnaireInput,
  TICK,
} from "@/serigraph/ui/questionnaire-choice"

// Questions one at a time on a plane with the big radius. No sheets peek out beneath it: depth belongs to drawings,
// so what is still to come shows in the progress instead, a row of numbers in small circles joined by short fine
// lines: a passed question takes the highlight and a fine ink tick, the current one a second ring round its line, and
// those still to come only a dashed line. The answering parts live in questionnaire-choice.tsx; the
// actions are the kit's pills, the main one last.

function Questionnaire({
  className,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Root>) {
  return (
    <QuestionnairePrimitive.Root
      data-slot="questionnaire"
      className={cn(
        "plane group/questionnaire relative flex w-full min-w-0 flex-col gap-snug p-snug sm:p-line",
        className,
      )}
      {...props}
    />
  )
}

function ProgressRings({ current, total }: { current: number; total: number }) {
  return (
    <span aria-hidden="true" className="flex flex-wrap items-center gap-y-1">
      {Array.from({ length: total }, (_, i) => {
        const state =
          i + 1 < current ? "done" : i + 1 === current ? "current" : "next"
        return (
          <React.Fragment key={i}>
            {i > 0 && (
              <span className="w-2.5 border-t-(length:--line) border-(--edge,var(--ink))" />
            )}
            <span
              data-state={state}
              className="relative flex size-6 items-center justify-center rounded-full border-(length:--line) border-ink bg-[color-mix(in_oklab,var(--surface,var(--canvas))_30%,var(--paper))] font-mono text-[0.6875rem] leading-none text-ink tabular-nums data-[state=current]:outline-(length:--line) data-[state=current]:outline-offset-2 data-[state=current]:outline-ink data-[state=done]:bg-highlight data-[state=next]:border-dashed data-[state=next]:border-(--edge,var(--ink)) data-[state=next]:bg-transparent data-[state=next]:text-(--text,var(--ink))"
            >
              {state === "done" ? (
                <svg
                  viewBox="0 0 14 14"
                  className="size-3 fill-none stroke-current [stroke-linecap:round] [stroke-linejoin:round]"
                >
                  <path d={TICK} strokeWidth={1.6} />
                </svg>
              ) : (
                i + 1
              )}
            </span>
          </React.Fragment>
        )
      })}
    </span>
  )
}

function QuestionnaireProgress({
  className,
  children,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Progress>) {
  return (
    <QuestionnairePrimitive.Progress
      data-slot="questionnaire-progress"
      className={cn(
        "flex min-h-[1lh] w-fit items-center gap-tight px-[3px] text-(--text,var(--ink))",
        className,
      )}
      render={(rendered, state) => {
        const { current, total } = state as { current: number; total: number }
        return (
          <div {...rendered}>
            <ProgressRings current={current} total={total} />
            {children ? (
              <span className="font-mono text-[0.75rem] tabular-nums">
                {children}
              </span>
            ) : null}
          </div>
        )
      }}
      {...props}
    />
  )
}

function QuestionnaireItem({
  className,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Item>) {
  // The item takes focus only by script, when a question opens; its answers carry the visible focus.
  return (
    <QuestionnairePrimitive.Item
      data-slot="questionnaire-item"
      className={cn(
        "m-0 flex min-w-0 animate-in flex-col gap-tight border-0 p-0 duration-(--duration-overlay) ease-(--ease) fade-in-0 outline-none",
        className,
      )}
      {...props}
    />
  )
}

function QuestionnaireTitle({
  className,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Title>) {
  return (
    <QuestionnairePrimitive.Title
      data-slot="questionnaire-title"
      className={cn(
        "float-left mb-0 w-full p-0 font-read text-lead leading-lead font-semibold text-pretty [&:not(:has(~[data-slot=questionnaire-description]))]:mb-hair",
        className,
      )}
      {...props}
    />
  )
}

function QuestionnaireDescription({
  className,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Description>) {
  return (
    <QuestionnairePrimitive.Description
      data-slot="questionnaire-description"
      className={cn(
        "m-0 -mt-1 mb-hair max-w-measure text-small leading-small text-pretty",
        className,
      )}
      {...props}
    />
  )
}

function QuestionnaireChoices({
  className,
  ...props
}: React.ComponentProps<typeof QuestionnairePrimitive.Choices>) {
  return (
    <QuestionnairePrimitive.Choices
      data-slot="questionnaire-choices"
      className={cn(
        "group/questionnaire-choices grid min-w-0 gap-tight",
        className,
      )}
      {...props}
    />
  )
}

function QuestionnaireActions({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="questionnaire-actions"
      className={cn(
        "grid min-h-control w-full grid-cols-[minmax(0,1fr)_auto_auto] items-center gap-tight pt-hair",
        className,
      )}
      {...props}
    />
  )
}

type Nav = Pick<React.ComponentProps<typeof Button>, "size" | "variant">
type NavPrimitive = typeof QuestionnairePrimitive.Next

// Previous, Skip, Next and Submit share one shape: a pill in a fixed column of the actions grid.
function navButton(
  Primitive: NavPrimitive,
  slot: string,
  place: string,
  fallback: string,
  defaultVariant: Nav["variant"],
) {
  return function QuestionnaireNavButton({
    children,
    className,
    size = "default",
    variant = defaultVariant,
    ...props
  }: React.ComponentProps<NavPrimitive> & Nav) {
    return (
      <Primitive
        data-slot={slot}
        data-size={size}
        data-variant={variant}
        className={cn(buttonVariants({ size, variant }), place, className)}
        {...props}
      >
        {children ?? fallback}
      </Primitive>
    )
  }
}

const QuestionnairePrevious = navButton(
  QuestionnairePrimitive.Previous,
  "questionnaire-previous",
  "col-start-1 row-start-1 justify-self-start",
  "Previous",
  "ghost",
)
const QuestionnaireSkip = navButton(
  QuestionnairePrimitive.Skip,
  "questionnaire-skip",
  "col-start-2 row-start-1 justify-self-end",
  "Skip",
  "outline",
)
const QuestionnaireNext = navButton(
  QuestionnairePrimitive.Next,
  "questionnaire-next",
  "col-start-3 row-start-1 justify-self-end",
  "Next",
  "default",
)
const QuestionnaireSubmit = navButton(
  QuestionnairePrimitive.Submit,
  "questionnaire-submit",
  "col-start-3 row-start-1 justify-self-end",
  "Submit",
  "default",
)

export {
  Questionnaire,
  QuestionnaireActions,
  QuestionnaireChoice,
  QuestionnaireChoiceDescription,
  QuestionnaireChoices,
  QuestionnaireDescription,
  QuestionnaireError,
  QuestionnaireInput,
  QuestionnaireItem,
  QuestionnaireNext,
  QuestionnairePrevious,
  QuestionnaireProgress,
  QuestionnaireSkip,
  QuestionnaireSubmit,
  QuestionnaireTitle,
}
